SOURCE = "\"\"\"\nThis job creates a set of loan features that will serve as input training data to a Model Server model\nthat searches for a set of comparable loans for a given target loan.\nThe output of this job includes standardized loan features:  each standardized variable ranges approximately from -3 to 3.\nWe can determine how similar any given pair of loans are by calculating the Euclidean distance between them.\nThe lower the distance that separates them, the more similar they are.\n\"\"\"\n\nfrom datetime import date\nfrom typing import List\n\nfrom datascience_jobs.dataset_downloader.downloaders.spark_dataset_downloader import SparkDatasetDownloader\nfrom datascience_jobs.meta_data.datasets.derived.pl_analytics.market_insights import ComparableLoansTrainingDataMetaData\nfrom datascience_jobs.meta_data.datasets.derived.pl_relationship_awareness.core import CoreLoanAccountsMetaData\nfrom datascience_jobs.meta_data.datasets.market_insights_historical.market_insights.validated_output import (\n    BankRegionLookupMetaData,\n    PostalCodeCountyLookupMetaData,\n)\nfrom datascience_jobs.meta_data.datasets.primary.pl_application.regions import RegionsMetaData\nfrom datascience_jobs.meta_data.datasets.primary.pl_application.users import UsersMetaData\nfrom datascience_jobs.meta_data.datasets.primary.pl_relationship_awareness.core import CoreAccountSupplementalDataMetaData\nfrom datascience_jobs.meta_data.datasets.primary.pl_relationship_awareness.relationships import RelationshipFinancialStatementsMetaData, RelationshipsMetaData\nfrom datascience_jobs.meta_data.enums import DatesToDownload\nfrom datascience_jobs.runner.base import BaseDatabricksRunner\nfrom datascience_jobs.utils import datascience_helpers as dh\nfrom datascience_jobs.utils import path\nfrom di_pyjobs.convention.log import log_empty_dataset_and_exit\nfrom pyspark.sql import DataFrame as sparkDataFrame\nfrom pyspark.sql import Window\nfrom pyspark.sql import functions as F\n\n# This dataset contains only the last 6 months of core loans for a client;\n# It is expected to be LESS THAN ~30MB for large clients and <1MB for small clients ==> repartitioning to 1\nREPARTITION_NUMBER = 1\n\nSOURCE_META_DATA = [\n    CoreLoanAccountsMetaData(major_version=2, dates_to_download=DatesToDownload.ALL_DATES),\n    CoreAccountSupplementalDataMetaData(major_version=1, dates_to_download=DatesToDownload.ALL_DATES, required=False),\n    RelationshipsMetaData(major_version=1, dates_to_download=DatesToDownload.ALL_DATES),\n    RelationshipFinancialStatementsMetaData(major_version=1, dates_to_download=DatesToDownload.ALL_DATES),\n    RegionsMetaData(major_version=1, dates_to_download=DatesToDownload.ALL_DATES),\n    UsersMetaData(major_version=2, dates_to_download=DatesToDownload.ALL_DATES),\n    BankRegionLookupMetaData(major_version=1, dates_to_download=DatesToDownload.ALL_DATES),\n    PostalCodeCountyLookupMetaData(major_version=1, dates_to_download=DatesToDownload.ALL_DATES),\n]\n\nOUTPUT_META_DATA = ComparableLoansTrainingDataMetaData(\n    major_version=ComparableLoansTrainingDataMetaData.LATEST_MAJOR_VERSION,\n    minor_version=ComparableLoansTrainingDataMetaData.LATEST_MINOR_VERSION,\n    dates_to_download=DatesToDownload.RUN_DATE,\n)\n\n\nMAX_AGE_DAYS = 180\nMIN_AMOUNT = 100\nRELATIONSHIP_FS_TYPE = 15  # STRATEGIC VALUE\nNULL_CUTOFF = 0.33\n\nDISTANCE_COLS = [\n    \"FtpCostOfFunds\",\n    \"AdjustableRateIndexRate\",\n    \"LogTerm\",\n    \"LogAmortizationTerm\",\n    \"LogAmount\",\n    \"DaysOld\",\n    \"LossGivenDefault\",\n    \"LogRelationshipCreditSize\",\n    \"AnnualLoss\",\n    \"Utilization\",\n]\n\nCOLS_TO_IMPUTE = [\n    \"StdFtpCostOfFunds\",\n    \"StdAdjustableRateIndexRate\",\n    \"StdLogTerm\",\n    \"StdLogAmortizationTerm\",\n    \"StdLogAmount\",\n    \"StdDaysOld\",\n    \"StdLossGivenDefault\",\n    \"StdLogRelationshipCreditSize\",\n    \"StdAnnualLoss\",\n    \"StdUtilization\",\n]\n\nLOAN_COLS = [\n    (\"CoreAccountId\", \"AccountId\"),\n    (\"RelationshipExternalId\", \"RelationshipExternalIdentifier\"),\n    (\"FacilityRating\",),\n    (\"RiskRating\",),\n    (\"OriginationDate\",),\n    (\"MaturityDate\",),\n    (\"ProductFamilyId\",),\n    (\"ProductName\",),\n    (\"Amount\",),\n    (\"Balance\",),\n    (\"RateType\",),\n    (\"PaymentType\",),\n    (\"Rate\",),\n    (\"InitialRate\",),\n    (\"FtpCostOfFunds\",),\n    (\"AdjustableRateSpread\",),\n    (\"AdjustableRateIndexRate\",),\n    (\"RemainingAmortizationTerm\",),\n    (\"OriginationFeeDollars\", \"FeesInitialDollars\"),\n    (\"FeesInitialPercentOfAmount\",),\n    (\"FeesAnnualDollars\",),\n    (\"FeesUnusedLoc\", \"FeesUnusedLOC\"),\n    (\"TaxExemptionOption\",),\n    (\"FtpRoe\", \"ROE\"),\n    (\"FtpTargetRoe\", \"TargetROE\"),\n    (\"FtpNetIncome\", \"NetIncome\"),\n    (\"LossGivenDefault\",),\n    (\"ProbabilityOfDefault\",),\n    (\"AnnualLoss12Months\",),\n    (\"AnnualLossUnbounded\",),\n    (\"LastRefreshDate\", \"LoanSaveDate\"),\n    (\"DatePartition\",),\n    (\"RelationshipOwnerId\",),\n    (\"OwnerId\", \"AccountOwnerId\"),\n    (\"RateIndex\",),\n]\n\nCOMPS_OUTPUT_COLS = [\n    \"ProductFamilyId\",\n    \"RegionId\",\n    \"RegionName\",\n    \"PostalCode\",\n    \"IndustryCode\",\n    \"AccountId\",\n    \"OriginationDate\",\n    \"RelationshipId\",\n    \"RelationshipName\",\n    \"TaxExemptionOption\",\n    \"IsTaxExempt\",\n    \"FacilityRating\",\n    \"RiskRating\",\n    \"ProductName\",\n    \"ProductGroup\",\n    \"IsLoc\",\n    \"ProbabilityOfDefault\",\n    \"AnnualLoss12Months\",\n    \"AnnualLossUnbounded\",\n    \"AdjustableRateSpread\",\n    \"ROE\",\n    \"TargetROE\",\n    \"NetIncome\",\n    \"FeesInitialDollars\",\n    \"FeesAnnualDollars\",\n    \"FeesUnusedLOC\",\n    \"Amount\",\n    \"Utilization\",\n    \"RateType\",\n    \"PaymentType\",\n    \"Rate\",\n    \"Maturity\",\n    \"RelationshipCreditSize\",\n    \"RelationshipDepositSize\",\n    \"RelationshipOtherSize\",\n    \"FtpCostOfFunds\",\n    \"AdjustableRateIndexRate\",\n    \"DaysOld\",\n    \"Term\",\n    \"AmortizationTerm\",\n    \"LossGivenDefault\",\n    \"AnnualLoss\",\n    \"FeesInitialPercentOfAmount\",\n    \"FeesInitialTotalRate\",\n    \"RelationshipOwnerId\",\n    \"AccountOwnerId\",\n    \"RateIndex\",\n]\n\nCOMPS_COLS_TYPES = [\n    (\"ProductFamilyId\", \"string\"),\n    (\"RegionId\", \"string\"),\n    (\"RegionName\", \"string\"),\n    (\"PostalCode\", \"string\"),\n    (\"IndustryCode\", \"string\"),\n    (\"AccountId\", \"string\"),\n    (\"OriginationDate\", \"date\"),\n    (\"RelationshipId\", \"string\"),\n    (\"RelationshipName\", \"string\"),\n    (\"TaxExemptionOption\", \"string\"),\n    (\"IsTaxExempt\", \"string\"),\n    (\"FacilityRating\", \"string\"),\n    (\"RiskRating\", \"string\"),\n    (\"ProductName\", \"string\"),\n    (\"ProductName\", \"string\"),\n    (\"IsLoc\", \"string\"),\n    (\"ProbabilityOfDefault\", \"float\"),\n    (\"AnnualLoss12Months\", \"float\"),\n    (\"AnnualLossUnbounded\", \"float\"),\n    (\"AdjustableRateSpread\", \"float\"),\n    (\"ROE\", \"float\"),\n    (\"TargetROE\", \"float\"),\n    (\"NetIncome\", \"int\"),\n    (\"FeesInitialDollars\", \"int\"),\n    (\"FeesAnnualDollars\", \"int\"),\n    (\"FeesUnusedLOC\", \"float\"),\n    (\"Amount\", \"int\"),\n    (\"Utilization\", \"float\"),\n    (\"RateType\", \"string\"),\n    (\"PaymentType\", \"string\"),\n    (\"Rate\", \"float\"),\n    (\"Maturity\", \"int\"),\n    (\"RelationshipCreditSize\", \"int\"),\n    (\"RelationshipDepositSize\", \"int\"),\n    (\"RelationshipOtherSize\", \"int\"),\n    (\"FtpCostOfFunds\", \"float\"),\n    (\"AdjustableRateIndexRate\", \"float\"),\n    (\"DaysOld\", \"int\"),\n    (\"Term\", \"float\"),\n    (\"AmortizationTerm\", \"float\"),\n    (\"LossGivenDefault\", \"float\"),\n    (\"AnnualLoss\", \"float\"),\n    (\"FeesInitialPercentOfAmount\", \"float\"),\n    (\"FeesInitialTotalRate\", \"float\"),\n    (\"RelationshipOwnerId\", \"string\"),\n    (\"AccountOwnerId\", \"string\"),\n    (\"RateIndex\", \"string\"),\n]\n\nREGION_COLS = [(\"RegionId\",), (\"RegionName\",)]\n\nUSER_COLS = [(\"UserId\",), (\"UserHomeRegionId\", \"RegionId\")]\n\nRELATIONSHIPS_COLS = [\n    (\"Id\", \"RelationshipId\"),\n    (\"ExternalIdentifier\", \"RelationshipExternalIdentifier\"),\n    (\"Name\", \"RelationshipName\"),\n    (\"OwnerId\",),\n    (\"PostalCode\",),\n    (\"IndustryCode\",),\n]\n\nRELATIONSHIPS_FS_COLS = [\n    (\"RelationshipId\",),\n    (\"RelationshipSubTotalTypeEnum\",),\n    (\"LoanAmount\", \"RelationshipCreditSize\"),\n    (\"DepositAverageBalance\", \"RelationshipDepositSize\"),\n    (\"OtherNetRevenue\", \"RelationshipOtherSize\"),\n]\n\n\ndef code_rate(data: sparkDataFrame) -> sparkDataFrame:\n    \"\"\"\n    Encodes rate type into standard deviation units\n\n    :param data: dataframe with RateType column\n    :returns: dataframe with RateType encoded\n    \"\"\"\n\n    data = data.withColumn(\n        \"StdRateType\",\n        F.when(F.col(\"RateType\") == \"Fixed\", -3.0)\n        .when(F.col(\"RateType\") == \"Float\", 2.0)\n        .when(F.col(\"RateType\") == \"Floating\", 2.0)\n        .when(F.col(\"RateType\") == \"Adjustable\", 3.0)\n        .otherwise(4.0),\n    )\n    return data\n\n\ndef code_payment_type(data: sparkDataFrame) -> sparkDataFrame:\n    \"\"\"\n    Encodes payment type into standard deviation units\n\n    :param data: dataframe with PaymentType column\n    :returns: dataframe with PaymentType encoded\n\n    \"1\": \"SinglePay\",\n    \"2\": \"Amortizing\",\n    \"4\": \"LOC\",\n    \"8\": \"ScheduledDraws\",\n    \"16\": \"ScheduledRepays\",\n    \"32\": \"ScheduledDrawsAndRepays\",\n    \"64\": \"LetterOfCredit\",\n    \"128\": \"LevelPrincipal\"\n    \"\"\"\n\n    data = data.withColumn(\n        \"StdPaymentType\",\n        F.when(F.col(\"PaymentType\") == \"LOC\", -3.0)\n        .when(F.col(\"PaymentType\") == \"Amortizing\", 0.5)\n        .when(F.col(\"PaymentType\") == \"SinglePay\", 1.5)\n        .when(F.col(\"PaymentType\") == \"LetterOfCredit\", 4.0)\n        .otherwise(2.5),\n    )\n\n    return data\n\n\ndef log_transform_cols(data: sparkDataFrame, cols: List[str]) -> sparkDataFrame:\n    \"\"\"\n    Log transforms provided list of columns. If the min value of the column is less than zero\n    adds the absolute minimum value plus 1 to every row to prevent taking the log of zero, or a negative number\n\n    :param data: dataframe with columns to transform\n    :param cols: names of columns to transform\n    :returns: data with log transformed columns added and prefixed with \"log\"\n    \"\"\"\n\n    expr_min = [F.min(col).alias(col + \"_min\") for col in cols]\n    min_vals = data.select(expr_min).collect()[0]\n\n    for col in cols:\n        col_min = col + \"_min\"\n        col_adjusted = col + \"_adjusted\"\n        col_log = \"Log\" + col\n\n        data = data.withColumn(col_min, F.lit(min_vals[col_min]))\n        data = data.withColumn(col_adjusted, F.when(F.col(col_min) <= 0, F.col(col) + F.abs(F.col(col_min)) + F.lit(1)).otherwise(F.col(col)))\n        data = data.withColumn(col_log, F.log(col_adjusted))\n        data = data.drop(col_min, col_adjusted)\n\n    return data\n\n\ndef standardize_num_cols(data: sparkDataFrame, cols: List[str]) -> sparkDataFrame:\n    \"\"\"\n    Centers and scales (z-score) all columns provided in a dataframe and adds Std prefix to column name.\n    log transforms column prefixed with Log in provided cols list\n\n    :param data: dataframe with numeric columns to center and scale\n    :param cols: names of columns to standardize if Log transform required Log should be prefixed to colname\n    :returns: dataframe with columns centered and scaled\n    \"\"\"\n    log_transforms = [col[3:] for col in cols if col.startswith(\"Log\")]\n    transformed = log_transform_cols(data, log_transforms)\n\n    # Pyspark does not allow for filling a column with a simple aggregation method\n    # Instead we have to create a one row dataframe with all aggregations and then\n    # Reference that for the mean and standard deviation values\n    mean_expr = [F.mean(col).alias(col + \"_mean\") for col in cols]\n    stddev_expr = [F.stddev(col).alias(col + \"_std\") for col in cols]\n\n    agg_values = transformed.select(mean_expr + stddev_expr).collect()[0]\n\n    for col in cols:\n        col_mean = col + \"_mean\"\n        col_stddev = col + \"_std\"\n        col_std = \"Std\" + col\n\n        transformed = transformed.withColumn(col_mean, F.lit(agg_values[col_mean]))\n        transformed = transformed.withColumn(col_stddev, F.lit(agg_values[col_stddev]))\n        transformed = transformed.withColumn(col_std, (F.col(col) - F.col(col_mean)) / F.col(col_stddev))\n        transformed = transformed.drop(col_stddev, col_mean)\n\n    return transformed\n\n\ndef format_loans_date_cols(core_loans: sparkDataFrame, today: date) -> sparkDataFrame:\n    \"\"\"\n    Formats date cols as dates and calculates days since origination. Assumes OriginationDate and MaturityDate\n    are in ISO format\n\n    :param core_loans: core loans dataframe\n    :param today: window start of current run\n    :returns: core_loans with days since origination calculated and date cols formatted\n    \"\"\"\n\n    core_loans = core_loans.withColumn(\"OriginationDate\", F.to_date(\"OriginationDate\"))\n    core_loans = core_loans.withColumn(\"MaturityDate\", F.to_date(F.col(\"MaturityDate\")))\n    core_loans = core_loans.withColumn(\"LoanSaveDate\", F.to_date(F.col(\"LoanSaveDate\").cast(\"string\"), \"yyyyMMdd\"))\n    core_loans = core_loans.withColumn(\"Today\", F.lit(today))\n    core_loans = core_loans.withColumn(\"DaysOld\", F.datediff(F.col(\"Today\"), F.col(\"OriginationDate\")))\n    core_loans = core_loans.withColumn(\"Maturity\", F.round(F.months_between(F.col(\"MaturityDate\"), F.col(\"OriginationDate\"))))\n    core_loans = core_loans.withColumn(\"Term\", F.months_between(F.col(\"MaturityDate\"), F.col(\"OriginationDate\")))\n    core_loans = core_loans.withColumn(\n        \"AmortizationTerm\", F.months_between(F.col(\"Today\"), F.col(\"OriginationDate\")) + F.expr(\"try_cast(RemainingAmortizationTerm as double)\")\n    )\n\n    return core_loans\n\n\ndef filter_loans(core_loans: sparkDataFrame, supplemental_data, max_age_days: int, min_amount: int) -> sparkDataFrame:\n    \"\"\"\n    Filter to subset of loans at origination that are acceptable for similar loans\n\n    :param core_loans: core_loans dataset filtered to loan records closest to their origination\n    :param supplemental_data: Core Loan supplemental data with column indicating loan aggregation or None\n    :param max_age_days: Max allowable age of a loan for inclusion in similar loans\n    :param min_amount: the minimum allowable amount of a loan for inclusion in similar loans\n    :returns: subset of core_loans at origination acceptable for inclusion in similar loans dataset\n    \"\"\"\n\n    core_loans_filtered = core_loans.filter(F.col(\"Amount\") > min_amount)\n    core_loans_filtered = core_loans_filtered.filter(F.col(\"DaysOld\") <= max_age_days)\n    # TODO: Consider reinstating this filter, when the Core Loans DDS adds LoanStatusEnum?\n    # 0 = not specified, 1 = active, 4 = new today\n    # core_loans_filtered = core_loans_filtered.filter(F.col('LoanStatusEnum').isin([0, 1, 4]))\n\n    # Remove aggregate loans\n    if supplemental_data:\n        supplemental_data = supplemental_data.withColumnRenamed(\"CoreAccountId\", \"AccountId\")\n        supplemental_data = supplemental_data.withColumnRenamed(\"DatePartition\", \"LoanSaveDate\")\n        supplemental_data = supplemental_data.select([\"LoanSaveDate\", \"AccountId\", \"IsAggregateData\"])\n        supplemental_data = supplemental_data.withColumn(\"LoanSaveDate\", F.to_date(F.col(\"LoanSaveDate\").cast(\"string\"), \"yyyyMMdd\"))\n\n        joined = core_loans_filtered.join(supplemental_data, on=[\"LoanSaveDate\", \"AccountId\"], how=\"left\")\n        # 1st: Wherever IsAggregateData is anything other than True (e.g. False or None or garbage), explicitly set it to False\n        joined = joined.withColumn(\"IsAggregateData\", F.when(F.col(\"IsAggregateData\"), True).otherwise(False))\n        # 2nd: Filter to keep only the non-aggregated loans (i.e. where IsAggregateData==False)\n        filtered = joined.filter(~F.col(\"IsAggregateData\"))\n        core_loans_filtered = filtered.drop(\"IsAggregateData\")\n\n    # If a loan is Fixed rate type, then it MUST have a non-null FTP Cost of Funds. IF IT DOESN'T: REMOVE THOSE PROBLEM LOANS!\n    core_loans_filtered = core_loans_filtered.filter(~((F.col(\"RateType\") == \"Fixed\") & (F.col(\"FtpCostOfFunds\").isNull())))\n    # Exclude loans that fail to have at least one valid measure of risk\n    core_loans_filtered = core_loans_filtered.filter(\n        (F.col(\"ProbabilityOfDefault\") != 0) | (F.col(\"AnnualLoss12Months\") != 0) | (F.col(\"AnnualLossUnbounded\") != 0)\n    )\n    # Exclude loans that have a Origination Date AFTER the Maturity Date. That data doesn't make sense so we throw them out.\n    core_loans_filtered = core_loans_filtered.filter(F.col(\"Term\") > 0)\n\n    return core_loans_filtered\n\n\ndef get_most_recent_origination_date_records(loans: sparkDataFrame) -> sparkDataFrame:\n    \"\"\"Get records for the most recent origination data for each account in core_loan pricing insights dataset\n\n    :param loans: core_loans dataset from market-insights-historical adls\n    :returns: most recent origination record for each lon\n    \"\"\"\n\n    loan_data = loans.withColumn(\"OrigDateRank\", F.dense_rank().over(Window.partitionBy([\"AccountId\"]).orderBy(F.desc(\"OriginationDate\"))))\n    loan_data = loan_data.filter(F.col(\"OrigDateRank\") == 1)\n    loan_data = loan_data.drop(\"OrigDateRank\")\n\n    return loan_data\n\n\ndef handle_missing(input_df: sparkDataFrame, col_list, null_cutoff: float) -> sparkDataFrame:\n    \"\"\"\n    1. Fills missing values with mean imputation (assumes data already standardized; the mean is 0 for any standardized variable)\n\n    2. Any column with greater than null_cutoff percentage of missing values gets nulled out (and later, in Model Server, will get dropped).\n        Note: 2 columns require special handling:\n        -  Handle case of StdAdjRateIndexRate: missing percentage should be calculated from only the rows wtih RateType != Fixed\n        -  Handle case of StdFtpCostOfFunds: missing percentage should be calculated from only the rows wtih RateType == Fixed\n\n    3. Columns with a missing-percentage that exceeds the null_cutoff will get nulled out. (Those columns will be dropped in Model Server.)\n    \"\"\"\n    # Make 3 dataframes with only the col_list columns, but with different numbers of rows\n    df = input_df.select(col_list)  # has the same number of rows as the input_df\n    df_fixed = df.filter(F.col(\"RateType\") == \"Fixed\")  # has only rows with Fixed Rate loans\n    df_variable = df.filter(F.col(\"RateType\") != \"Fixed\")  # has only rows with variable rate loans (i.e. floating or adjustable)\n    df_LOC = df.filter(F.col(\"PaymentType\") == \"LOC\")  # has only rows with LOC payment types\n\n    # Get number of applicable rows to use in the calculation of the missing-percentage. (Cast to float to avoid integer division later on)\n    num_rows = float(df.count())  # applies to all columns OTHER THAN ['StdAdjustableRateIndexRate', 'StdFtpCostOfFunds']\n    if num_rows <= 0:\n        return None\n    num_rows_fixed = float(df_fixed.count())  # applies to the column 'StdFtpCostOfFunds'\n    num_rows_variable = float(df_variable.count())  # applies to the column 'StdAdjustableRateIndexRate'\n    num_rows_LOC = float(df_LOC.count())  # applies to the column 'StdUtilization'\n\n    # Get the count of missing (i.e. nan or null) values from among the applicable rows per column\n    missing_counts = df.select([F.count(F.when((F.isnan(c)) | (F.col(c).isNull()), c)).alias(c) for c in df.columns])\n    missing_ftp_cof = float((df_fixed.filter(F.isnan(\"StdFtpCostOfFunds\") | F.col(\"StdFtpCostOfFunds\").isNull())).count())\n    missing_adj_rate = float((df_variable.filter(F.isnan(\"StdAdjustableRateIndexRate\") | F.col(\"StdAdjustableRateIndexRate\").isNull())).count())\n    missing_util = float((df_LOC.filter(F.isnan(\"StdUtilization\") | F.col(\"StdUtilization\").isNull())).count())\n\n    cols_to_drop = []\n    cols_to_keep = col_list\n    for col in col_list:\n        # Identify the columns that have a missing-percentage > null_cutoff\n        if col not in [\"StdAdjustableRateIndexRate\", \"StdFtpCostOfFunds\", \"StdUtilization\"]:\n            missing_counts = missing_counts.withColumn(col, (1.0 / num_rows) * F.col(col))\n            if missing_counts.select(col).collect()[0][0] > null_cutoff:\n                cols_to_drop.append(col)\n                cols_to_keep.remove(col)\n\n        elif col == \"StdAdjustableRateIndexRate\":\n            # if EITHER num_rows_variable == 0\n            if (num_rows_variable == 0) | (missing_adj_rate / num_rows_variable > null_cutoff):\n                cols_to_drop.append(col)\n                cols_to_keep.remove(col)\n\n        elif col == \"StdFtpCostOfFunds\":\n            if num_rows_fixed == 0:\n                cols_to_drop.append(col)\n                cols_to_keep.remove(col)\n            elif missing_ftp_cof / num_rows_fixed > null_cutoff:\n                cols_to_drop.append(col)\n                cols_to_keep.remove(col)\n\n        elif col == \"StdUtilization\":\n            if (num_rows_LOC == 0) | (missing_util / num_rows_LOC > null_cutoff):\n                cols_to_drop.append(col)\n                cols_to_keep.remove(col)\n\n    # Handle the cols_to_drop: Set them equal to F.lit(None)\n    for col in cols_to_drop:\n        input_df = input_df.withColumn(col, F.lit(None))\n\n    # Handle the cols_to_keep: Fill missing values with the average value, which for standardized columns is always equal to 0.\n    imputed_df = input_df.na.fill(value=0.0, subset=cols_to_keep)\n\n    return imputed_df\n\n\nclass ComparableLoansTrainingData(BaseDatabricksRunner):\n    META = OUTPUT_META_DATA\n\n    def upload(self, dataframe: sparkDataFrame, output_path: str, repartition_number: int = 1):\n        dataframe.repartition(repartition_number).write.mode(\"overwrite\").save(output_path, format=\"parquet\", header=True)\n\n    def _run(self, client_id, rundate_dt):  # rundate is of type datetime\n        dataset_downloader = SparkDatasetDownloader.from_runner(SOURCE_META_DATA, runner=self)\n        dataset_downloader.set_uris()\n        dataset_downloader.download()\n\n        if dataset_downloader.is_missing_required_dataset():\n            return None\n\n        dataset_downloader.filter_less_than_equal_to_date_col()\n        dataset_downloader.filter_latest_minor_version_per_id_cols()\n\n        loans = dataset_downloader.return_df(\"CoreLoanAccounts\")\n        if loans.count() <= 0:\n            self.logger.info(\"Input loan count is 0.\")\n            return None\n        loan_supplemental_data = dataset_downloader.return_df(\"CoreAccountSupplementalData\")\n        regions = dataset_downloader.return_df(\"Regions\")\n        users = dataset_downloader.return_df(\"Users\")\n        relationships = dataset_downloader.return_df(\"Relationships\")\n        relationship_financial_statements = dataset_downloader.return_df(\"RelationshipFinancialStatements\")\n        mi_regions = dataset_downloader.return_df(\"BankRegionLookup\")\n        zip2county = dataset_downloader.return_df(\"PostalCodeCountyLookup\")\n\n        # Latest Filtering\n        mi_regions_latest = dh.get_latest_entry_by_date(mi_regions, [\"state_id\", \"county_name\"], \"DatePartition\", F.row_number)\n        regions_latest = dh.get_latest_entry_by_date(regions, [\"RegionId\"], \"DatePartition\", F.row_number)\n        users_latest = dh.get_latest_entry_by_date(users, [\"UserId\"], \"DatePartition\", F.row_number)\n        relationships_latest = dh.get_latest_entry_by_date(relationships, \"ExternalIdentifier\", \"DatePartition\", F.row_number)\n        relationships_fs_latest = dh.get_latest_entry_by_date(\n            relationship_financial_statements, [\"RelationshipId\", \"RelationshipSubTotalTypeEnum\"], \"DatePartition\", F.row_number\n        )\n\n        # Column Selection and Renaming\n        mi_regions_latest = mi_regions_latest.drop(\"DatePartition\").drop(\"clientId\")\n        zip2county_2 = (\n            zip2county.withColumnRenamed(\"postalCode\", \"PostalCode\").withColumnRenamed(\"state\", \"state_id\").withColumnRenamed(\"county\", \"county_name\")\n        )\n        regions_selection, _ = dh.update_data(regions_latest, REGION_COLS)\n        users_selection, _ = dh.update_data(users_latest, USER_COLS)\n        relationships_selection, _ = dh.update_data(relationships_latest, RELATIONSHIPS_COLS)\n        relationships_fs_selection, _ = dh.update_data(relationships_fs_latest, RELATIONSHIPS_FS_COLS)\n        loans_selection, _ = dh.update_data(loans, LOAN_COLS)\n\n        # Loan Processing\n        loans_dates = format_loans_date_cols(loans_selection, rundate_dt)\n        loans_dates = loans_dates.fillna(0.0, subset=[\"FeesInitialDollars\", \"FeesInitialPercentOfAmount\"])\n        loans_dates = loans_dates.withColumn(\"FeesInitialTotalRate\", F.col(\"FeesInitialPercentOfAmount\") + F.col(\"FeesInitialDollars\") / F.col(\"Amount\"))\n\n        # Get loans closest to origination\n        loans_recent_origination = get_most_recent_origination_date_records(loans_dates)\n        loans_aligned = dh.align_data_by_date(loans_recent_origination, \"LoanSaveDate\", \"OriginationDate\", [\"AccountId\"])\n\n        # Filter loans\n        loans_filtered = filter_loans(loans_aligned, loan_supplemental_data, MAX_AGE_DAYS, MIN_AMOUNT)\n        if loans_filtered.count() <= 0:\n            self.logger.info(\"After filtering, the loan count is 0.\")\n            return None\n        # New function for Comps; Gita's methodology: \"AnnualLoss\" = coalesce(probability of default, 12 mo annual loss, unbounded loss)\n        loans_clean = loans_filtered.withColumn(\n            \"AnnualLoss\", F.coalesce(F.col(\"ProbabilityOfDefault\"), F.col(\"AnnualLoss12Months\"), F.col(\"AnnualLossUnbounded\"))\n        )\n        loans_clean = loans_clean.withColumn(\"IsTaxExempt\", F.when(F.col(\"TaxExemptionOption\") == \"NotTaxExempt\", \"NotTaxExempt\").otherwise(\"TaxExempt\"))\n        loans_clean = loans_clean.withColumn(\"IsLoc\", F.when(F.col(\"PaymentType\") == \"LOC\", \"LOC\").otherwise(\"NotLOC\"))\n        loans_clean = loans_clean.withColumn(\n            \"AdjustableRateIndexRate\", F.when(F.col(\"RateType\") == \"Fixed\", F.lit(None)).otherwise(F.col(\"AdjustableRateIndexRate\"))\n        )\n        loans_clean = loans_clean.withColumn(\"FtpCostOfFunds\", F.when(F.col(\"RateType\") != \"Fixed\", F.lit(None)).otherwise(F.col(\"FtpCostOfFunds\")))\n\n        loans_clean = loans_clean.withColumn(\"ProductNameLowercase\", F.lower(F.col(\"ProductName\")))\n        loans_clean = loans_clean.withColumn(\n            \"ProductGroup\",\n            F.when((F.col(\"ProductNameLowercase\").like(\"%letter of credit%\")) | (F.col(\"ProductNameLowercase\").like(\"%letters of credit%\")), \"Letter of Credit\")\n            .when(F.col(\"ProductName\").like(\"%CRE%\"), \"CRE\")\n            .when((F.col(\"ProductNameLowercase\").like(\"%ppp%\")) | (F.col(\"ProductNameLowercase\").like(\"%paycheck protection%\")), \"PPP\")\n            .when(F.col(\"ProductNameLowercase\").like(\"%lease%\"), \"Lease\")\n            .when(\n                (F.col(\"ProductNameLowercase\").like(\"%comm%\"))\n                & (\n                    (F.col(\"ProductNameLowercase\").like(\"%real%\"))\n                    | (F.col(\"ProductNameLowercase\").like(\"%prop%\"))\n                    | (F.col(\"ProductNameLowercase\").like(\"%mort%\"))\n                    | (F.col(\"ProductNameLowercase\").like(\"%land%\"))\n                    | (F.col(\"ProductNameLowercase\").like(\"%constr%\"))\n                ),\n                \"CRE\",\n            )\n            .when(F.col(\"ProductNameLowercase\").like(\"%consumer%\"), \"Consumer\")\n            .when(F.col(\"ProductNameLowercase\").like(\"%construction%\"), \"CRE\")\n            .when(F.col(\"ProductName\").like(\"%RE%\"), \"CRE\")\n            .when(F.col(\"ProductName\").like(\"% cre %\"), \"CRE\")\n            .otherwise(F.lit(\"CI\")),\n        )\n\n        # Prep relationship data\n        relationships_fs_filtered = relationships_fs_selection.filter(F.col(\"RelationshipSubTotalTypeEnum\") == RELATIONSHIP_FS_TYPE)\n        relationships_selection = relationships_selection.withColumn(\n            \"PostalCode\", F.substring(F.trim(F.col(\"PostalCode\")), 1, 5)\n        )  # Get the 5-digit zip code, to prepare for join wtih zip2county_2\n        relationships_joined = relationships_selection.join(relationships_fs_filtered, on=\"RelationshipId\", how=\"inner\")\n        relationships_clean = dh.get_latest_entry_by_date(relationships_joined, [\"RelationshipExternalIdentifier\"], \"RelationshipCreditSize\", F.row_number)\n\n        # Join to create final dataset\n        final_joins = dh.join_datasets(\n            data=loans_clean,\n            data_list=[relationships_clean, users_selection, regions_selection],\n            on_list=[\"RelationshipExternalIdentifier\", F.col(\"OwnerId\") == F.col(\"UserId\"), \"RegionId\"],\n            how_list=[\"left\", \"left\", \"left\"],\n        )\n\n        # Comparable Loans Processing\n        final_joins = final_joins.withColumn(\"Utilization\", F.when(F.col(\"PaymentType\") == \"LOC\", F.col(\"Balance\") / F.col(\"Amount\")).otherwise(F.lit(None)))\n        # Utilization should be between 0 and 1. I chose to right-truncate it at 1.1 to allow for overdrawn lines,\n        # This prevents outliers like 500000 from robbing Utilization of its predictive power in the \"valid\" range of 0 to 1.\n        final_joins = final_joins.withColumn(\n            \"Utilization\", F.when(F.col(\"Utilization\") >= 1.1, 1.1).otherwise(F.col(\"Utilization\"))\n        )  # right truncate Utilization at 1.1\n        final_joins = final_joins.withColumn(\n            \"Utilization\", F.when(F.col(\"Utilization\") < 0, 0).otherwise(F.col(\"Utilization\"))\n        )  # left truncate Utilization at 0\n        # Negative values of Relationship Credit Size mean essentially the same thing as 0: \"No outstanding balance on any loans.\"\n        # Therefore, let's left-truncate it to 0.\n        final_joins = final_joins.withColumn(\n            \"RelationshipCreditSize\", F.when(F.col(\"RelationshipCreditSize\") <= 0, 0).otherwise(F.col(\"RelationshipCreditSize\"))\n        )  # left truncate RelationshipCreditSize at 0\n        final_joins = final_joins.select(COMPS_OUTPUT_COLS)\n        final_joins = dh.change_column_data_type(final_joins, COMPS_COLS_TYPES)\n\n        final_joins = final_joins.cache()\n        final_joins_std = standardize_num_cols(final_joins, DISTANCE_COLS)\n\n        final_joins_coded_rate_type = code_rate(final_joins_std)\n        final_joins_coded_payment_type = code_payment_type(final_joins_coded_rate_type)\n        # Fill missing values where appropriate; Null out columns with \"too many\" missing values. Assumes COLS_TO_IMPUTE are standardized\n        final_joins_imputed = handle_missing(final_joins_coded_payment_type, COLS_TO_IMPUTE, NULL_CUTOFF)\n        if final_joins_imputed is None:\n            self.logger.info(\"After handling missing values, the loan count is 0.\")\n            return None\n\n        # Add in Market Bank Region\n        with_county = final_joins_imputed.join(zip2county_2, \"PostalCode\", \"left\")\n        with_region = with_county.join(\n            mi_regions_latest, ((with_county.state_id == mi_regions_latest.state_id) & (with_county.county_name == mi_regions_latest.county_name)), \"left\"\n        )\n        with_region = with_region.withColumn(\"MarketBankRegion\", F.when(F.col(\"region\").isNull(), F.lit(\"USA\")).otherwise(F.col(\"region\")))\n        with_region = with_region.select(self.META.columns)\n        with_region = dh.change_column_data_type(with_region, self.META.columns_spark_dtypes)\n        return with_region\n\n    def run(self):\n        adls_uri = path.spark_uri_from_contx_resource(self.context.get(path.HISTORICAL_L3_RESOURCE), path.HISTORICAL_L3_CONTAINER)\n        data = self._run(self.activity.client_id, self.activity.window_start)  # Passes in rundate as a datetime, e.g. 2022-11-10 05:00:00\n\n        if data is None or data.count() < 1:\n            log_empty_dataset_and_exit(self.logger, self.activity.name)\n\n        self.META.set_contx_path(run_id=self.activity.run_id, client_id=self.activity.client_id, window_start=self.activity.window_start_timestamp)\n        self.META.set_wildcard_uri(adls_uri)\n        self.logger.info(f\"output_path_report {self.META.wildcard_uri}\")\n\n        return self.upload(dataframe=data, output_path=self.META.wildcard_uri, repartition_number=REPARTITION_NUMBER)\n"
if hashlib.sha256(SOURCE.encode()).hexdigest() != SOURCE_SHA256:
    raise ValueError("Pinned source digest mismatch")
tree = ast.parse(SOURCE)
functions = [n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "handle_missing"]
if len(functions) != 1 or functions[0].decorator_list:
    raise ValueError("Require exactly one original undecorated helper")
constants = {}
for statement in tree.body:
    if isinstance(statement, ast.Assign) and len(statement.targets) == 1 and isinstance(statement.targets[0], ast.Name):
        if statement.targets[0].id in {"COLS_TO_IMPUTE", "NULL_CUTOFF"}:
            constants[statement.targets[0].id] = ast.literal_eval(statement.value)
if set(constants) != {"COLS_TO_IMPUTE", "NULL_CUTOFF"}:
    raise ValueError("Missing original literal call arguments")
namespace = {"F": F}
module = ast.fix_missing_locations(ast.Module(body=functions, type_ignores=[]))
exec(compile(module, SOURCE_PATH, "exec", flags=__future__.annotations.compiler_flag), namespace)
helper = namespace["handle_missing"]
session = spark.newSession()
session.conf.set("spark.sql.ansi.enabled", "false")
session.conf.set("spark.sql.session.timeZone", "UTC")
session.conf.set("spark.sql.shuffle.partitions", "2")
columns = list(constants["COLS_TO_IMPUTE"])
schema = "CaseRowId string, RateType string, PaymentType string, " + ", ".join(c + " double" for c in columns)


def make_rows(mode: str = "mixed", missing: tuple[str, ...] = ()) -> list[dict]:
    """Create two synthetic records with explicit applicable subpopulations."""
    rows = []
    for i in range(2):
        row = {"CaseRowId": str(i), "RateType": "Fixed" if mode == "no_variable" or i == 0 else "Float",
               "PaymentType": "Amortizing" if mode == "no_loc" else "LOC"}
        row.update({c: None if c in missing else 1.0 for c in columns})
        rows.append(row)
    return rows


def run_case(name: str, rows: list[dict], selected: list[str], cutoff: float,
             expectation: str, reuse: bool = False) -> dict:
    """Run the unmodified helper and retain results or source-local failure."""
    selected = list(selected)
    before = list(selected)
    frame = session.createDataFrame(rows, schema=schema)
    result = {"name": name, "expectation": expectation, "input_rows": rows,
              "columns_before": before, "cutoff": cutoff}
    try:
        output = helper(frame, selected, cutoff)
        result["status"] = "returned"
        result["output_rows"] = None if output is None else [r.asDict() for r in output.orderBy("CaseRowId").collect()]
        result["output_columns"] = None if output is None else output.columns
        if reuse:
            again = helper(frame, selected, cutoff)
            result["second_output_rows"] = None if again is None else [r.asDict() for r in again.orderBy("CaseRowId").collect()]
    except Exception as error:
        result["status"] = "error"
        result["error_type"] = type(error).__name__
        result["error"] = str(error)[:2000]
        result["original_source_lines"] = [t.lineno for t in traceback.extract_tb(error.__traceback__) if t.filename == SOURCE_PATH]
    result["columns_after"] = list(selected)
    return result


results = []
cutoff = constants["NULL_CUTOFF"]
results.append(run_case("baseline_actual_columns", make_rows(), columns, cutoff,
                        "No missing features: preserve numeric ones."))
results.append(run_case("no_variable_rows", make_rows("no_variable"), columns, cutoff,
                        "Zero variable loans should take the zero-row guard without dividing."))
results.append(run_case("no_loc_rows", make_rows("no_loc"), columns, cutoff,
                        "Zero LOC loans should take the zero-row guard without dividing."))
missing = ("StdLogTerm", "StdLogAmortizationTerm")
results.append(run_case("adjacent_all_missing_actual_order", make_rows(missing=missing), columns, cutoff,
                        "Both 100-percent-missing features exceed the source cutoff and should remain null.", reuse=True))
swapped = list(columns)
a, b = swapped.index(missing[0]), swapped.index(missing[1])
swapped[a], swapped[b] = swapped[b], swapped[a]
results.append(run_case("adjacent_all_missing_reversed_order", make_rows(missing=missing), swapped, cutoff,
                        "Reordering feature selectors should preserve the missingness rule."))
boundary_rows = make_rows()
boundary_rows[0]["StdLogTerm"] = None
results.append(run_case("missing_fraction_equal_cutoff", boundary_rows, columns, 0.5,
                        "Exactly half missing equals cutoff: impute null to zero."))
results.append(run_case("missing_fraction_above_cutoff", boundary_rows, columns, 0.49,
                        "Half missing exceeds cutoff: null the feature for both records."))
results.append(run_case("missing_fraction_below_cutoff", boundary_rows, columns, 0.51,
                        "Half missing below cutoff: impute null to zero."))
control = session.createDataFrame([(None,), (float("nan"),), (1.0,)], "feature double")
original_count = control.select(F.count(F.when(F.isnan("feature") | F.col("feature").isNull(), "feature")).alias("missing")).first()["missing"]
results.append({"name": "missing_counter_negative_control", "status": "returned",
                "expectation": "The string result is a literal, so the original counter should count both null and NaN.",
                "observed_count": original_count, "expected_count": 2})

dbutils.notebook.exit(json.dumps({
    "format": "q2-contradiction-diagnostic/v1",
    "source": {"commit": SOURCE_COMMIT, "path": SOURCE_PATH, "sha256": SOURCE_SHA256},
    "function": "handle_missing", "source_start_line": functions[0].lineno,
    "spark_version": session.version, "data": "synthetic_only",
    "source_modified": False, "whole_job_coverage": False,
    "scenario_subcases": len(results), "results": results,
}, sort_keys=True, allow_nan=False))
